    "name": "policy_name",
    "type": "string",
    "description": "The name of the policy.",
    "required": true
   },
   {
    "name": "policy_description",
    "type": "string",
    "description": "A brief description of the policy.",
    "required": true
   },
   {
    "name": "policy_type",
    "type": "string",
    "description": "The type of the policy. One of ['whitelist', 'blacklist'].",
    "required": true
   },
   {
